couple LEDDriverChipSystem
import architectureModels.BrightnessControl as BrightnessControl;
import architectureModels.CurrentControl as CurrentControl;
import architectureModels.ColorControl as ColorControl;
part:
    BrightnessControl brightnessControlInstance;
    CurrentControl currentControlInstance;
    ColorControl colorControlInstance;
connection:
    connect(brightnessControlInstance.BrightnessLevel, currentControlInstance.SetBrightness);
    connect(brightnessControlInstance.DefaultSignal, currentControlInstance.ResetSettings);
    connect(currentControlInstance.CurrentLevel, colorControlInstance.SetCurrent);
    connect(currentControlInstance.DefaultSignal, colorControlInstance.ResetSettings);
end;
